# CDL Failure Mode Identifiers - NOT the J1939 FMI list (that one lives in
# lookup/spn.py). CAT's CDL FMIs are a different, shorter vocabulary, and
# the published document skips 15-18. Confirmed in cited live code lists:
# "FMI:9 Abnormal Update Rate", "FMI:14 Special Instruction".
CAT_CDL_FMI: dict[int, str] = {
    0: 'High',
    1: 'Low',
    2: 'Erratic, Intermittent, or Incorrect',
    3: 'Voltage Above Normal',
    4: 'Voltage Below Normal',
    5: 'Current Below Normal',
    6: 'Current Above Normal',
    7: 'Not Responding Properly',
    8: 'Abnormal Frequency, Pulse Width, or Period',
    9: 'Abnormal Update Rate',
    10: 'Abnormal Rate of Change',
    11: 'Other Failure Mode',
    12: 'Failure',
    13: 'Out of Calibration',
    14: 'Special Instruction',
    19: 'Data Error',
    20: 'Data Drifted High',
    21: 'Data Drifted Low',
}
